const data = $getWorkflowStaticData('global');
data.pending = data.pending || {};

const update = $input.first().json;
const now = Date.now();
const TTL_MS = 5 * 60 * 1000;

for (const cid in data.pending) {
  if (data.pending[cid].expiresAt < now) delete data.pending[cid];
}

let chatId, text = '', callbackData, callbackId;

if (update.message) {
  chatId = update.message.chat?.id;
  text = (update.message.text || '').trim();
} else if (update.callback_query) {
  chatId = update.callback_query.message?.chat?.id;
  callbackData = update.callback_query.data;
  callbackId = update.callback_query.id;
} else {
  return [];
}

if (!chatId) return [];

const pending = data.pending[chatId];

const UUID_RE = /([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})/i;
const CHAPTER_URL_RE = /mangadex\.org\/chapter\/([0-9a-f-]{36})/i;

const out = (action, extra = {}) => [{
  json: { action, chatId, callbackId: callbackId || null, ...extra }
}];

if (text === '/cancel' || callbackData === 'cancel') {
  if (pending) delete data.pending[chatId];
  return out('reply_only', { text: '\u274C Cancelled.' });
}

if (text === '/start' || text === '/help') {
  return out('reply_only', {
    text: '*MangaBrainRot bot*\n\nDrop a MangaDex chapter URL or UUID and I will walk you through making a reel.\n\n`/cancel` aborts an in-progress flow.'
  });
}

if (callbackData) {
  if (!pending) {
    return out('reply_only', { text: '\u23F0 Session expired. Send the chapter URL again.' });
  }

  if (pending.step === 'awaiting_choice' && callbackData === 'skip') {
    const dispatched = { ...pending };
    delete data.pending[chatId];
    return out('dispatch_wfb', {
      mangaId: dispatched.mangaId,
      chapterId: dispatched.chapterId,
      title: dispatched.title,
      chapterNum: dispatched.chapterNum,
      thumbUrl: '',
      prompt: '',
      ackText: '\uD83C\uDFAC Generating reel (no AI thumbnail). Check Instagram in ~2 min.'
    });
  }

  if (pending.step === 'awaiting_choice' && callbackData === 'prompt') {
    pending.step = 'awaiting_prompt';
    pending.expiresAt = now + TTL_MS;
    return out('reply_only', {
      text: '\uD83D\uDCDD Send your thumbnail prompt.\n\nE.g. "Ayanokoji shirtless, glowing eyes, cracking abs, WHAT?? text overlay"\n\n`/cancel` to abort.'
    });
  }

  if (pending.step === 'awaiting_confirm' && callbackData === 'post') {
    const dispatched = { ...pending };
    delete data.pending[chatId];
    return out('dispatch_wfb', {
      mangaId: dispatched.mangaId,
      chapterId: dispatched.chapterId,
      title: dispatched.title,
      chapterNum: dispatched.chapterNum,
      thumbUrl: dispatched.thumbUrl,
      prompt: dispatched.prompt,
      ackText: '\uD83C\uDFAC Generating reel with your AI thumbnail. Check Instagram in ~2 min.'
    });
  }

  if (pending.step === 'awaiting_confirm' && callbackData === 'retry') {
    pending.step = 'awaiting_prompt';
    pending.expiresAt = now + TTL_MS;
    return out('reply_only', {
      text: '\uD83D\uDD01 Send a new thumbnail prompt.\n\n`/cancel` to abort.'
    });
  }

  return out('reply_only', { text: '\uD83E\uDD14 Stale button. /cancel and start over.' });
}

if (pending && pending.step === 'awaiting_prompt') {
  if (!text) return out('reply_only', { text: 'Send a prompt or /cancel.' });
  pending.prompt = text;
  pending.expiresAt = now + TTL_MS;
  return out('generate_thumbnail', { prompt: text, title: pending.title });
}

const chapterMatch = (text.match(CHAPTER_URL_RE) || [])[1] || (text.match(UUID_RE) || [])[1];
if (chapterMatch) {
  return out('resolve_chapter', { chapterId: chapterMatch.toLowerCase() });
}

return out('reply_only', { text: 'Drop a MangaDex chapter URL or UUID to start. `/help` for commands.' });

const route = $('Route').first().json;
const chapter = $input.first().json;
const rels = chapter?.data?.relationships || [];
const mangaRel = rels.find(r => r.type === 'manga');
if (!mangaRel?.id) {
  return [{ json: { _error: true, chatId: route.chatId, text: '\u274C Could not resolve manga from chapter.' } }];
}
const attrs = chapter.data.attributes || {};
const chapterNum = parseFloat(attrs.chapter);
return [{ json: {
  chatId: route.chatId,
  chapterId: route.chapterId,
  mangaId: String(mangaRel.id).toLowerCase(),
  chapterNum: isNaN(chapterNum) ? null : chapterNum
}}];

const data = $getWorkflowStaticData('global');
data.pending = data.pending || {};
const ctx = $('Extract mangaId').first().json;
const manga = $input.first().json;
const titles = manga?.data?.attributes?.title || {};
const title = titles.en || titles['ja-ro'] || titles.ja || Object.values(titles)[0] || ctx.mangaId;
const TTL_MS = 5 * 60 * 1000;
data.pending[ctx.chatId] = {
  step: 'awaiting_choice',
  chapterId: ctx.chapterId,
  mangaId: ctx.mangaId,
  title,
  chapterNum: ctx.chapterNum,
  expiresAt: Date.now() + TTL_MS
};
const chNum = ctx.chapterNum != null ? ` \u2014 Ch. ${ctx.chapterNum}` : '';
return [{ json: {
  chatId: ctx.chatId,
  text: `\uD83D\uDCD6 *${title}*${chNum}\n\nWant a clickbait AI thumbnail or skip it?`
}}];

const data = $getWorkflowStaticData('global');
data.pending = data.pending || {};
const route = $('Route').first().json;
const upload = $input.first().json;
const TTL_MS = 5 * 60 * 1000;
const pending = data.pending[route.chatId];
if (!pending) {
  return [{ json: { chatId: route.chatId, _error: true, text: '\u23F0 Session expired during generation.' } }];
}
pending.thumbUrl = upload.url;
pending.step = 'awaiting_confirm';
pending.expiresAt = Date.now() + TTL_MS;
const chNum = pending.chapterNum != null ? ` \u2014 Ch. ${pending.chapterNum}` : '';
return [{ json: {
  chatId: route.chatId,
  thumbUrl: upload.url,
  caption: `\uD83D\uDDBC Preview for *${pending.title}*${chNum}.\n\nPost it, retry the prompt, or cancel?`
}}];
